-- Append-only guard (README rule 7, spec 03 section 3.6): refuses UPDATE, DELETE and TRUNCATE. Trigger arguments
-- name columns a documented service may still update (for example iam.sessions.last_seen_at).
create or replace function meta.tg_refuse_change() returns trigger
language plpgsql as $fn$
begin
    if tg_op = 'UPDATE' and tg_nargs > 0 and (to_jsonb(new) - tg_argv) = (to_jsonb(old) - tg_argv) then
        return new;
    end if;
    raise exception 'append-only table %.%: % is not allowed', tg_table_schema, tg_table_name, tg_op
        using errcode = 'ER001';
end
$fn$;

-- meta.inbox_messages: Messages already processed by a consumer, so consumers are idempotent (spec 03 section 7.5)
create table if not exists meta.inbox_messages (
    message_id uuid not null,
    consumer text not null,
    processed_at timestamptz not null,
    constraint pk_inbox_messages primary key (message_id, consumer)
);

-- meta.local_entitlement: Copy of the current entitlement used by the licence guard [KRN-ENT-04]
create table if not exists meta.local_entitlement (
    id uuid not null,
    payload jsonb not null,
    signature bytea not null,
    state text not null,
    state_since timestamptz not null,
    highest_time_seen timestamptz not null,
    created_at timestamptz not null,
    created_by uuid not null,
    updated_at timestamptz not null,
    updated_by uuid not null,
    row_version bigint not null default 1,
    constraint pk_local_entitlement primary key (id)
);

-- meta.outbox_messages: Events written in the business transaction; the dispatcher publishes them (spec 03 section 7.5)
create table if not exists meta.outbox_messages (
    id uuid not null,
    occurred_at timestamptz not null,
    event_type text not null,
    aggregate_type text not null,
    aggregate_id uuid not null,
    payload jsonb not null,
    headers jsonb not null default '{}'::jsonb,
    published_at timestamptz,
    constraint pk_outbox_messages primary key (id)
);
create index if not exists ix_outbox_messages_occurred_at_unpublished on meta.outbox_messages (occurred_at) where (published_at is null); -- dispatcher reads unpublished messages in order

